import{_ as t,a0 as d,w as o,s as r,ao as l,I as n,x as a,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Linux 中使用 parted 对磁盘分区 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 parted 对磁盘分区 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 parted 对磁盘分区 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 parted 对磁盘分区 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180611 How to partition a disk in Linux","title":"如何在 Linux 中使用 parted 对磁盘分区","tag":"201806","desc":""},"relativePath":"201806/20180611 How to partition a disk in Linux.md","filePath":"[post].md"}'),u={name:"201806/20180611 How to partition a disk in Linux.md"};function c(h,s,k,f,g,b){const e=d("Link");return o(),r("div",null,[s[30]||(s[30]=l('<h1 id="如何在-linux-中使用-parted-对磁盘分区" tabindex="-1">如何在 Linux 中使用 parted 对磁盘分区 <a class="header-anchor" href="#如何在-linux-中使用-parted-对磁盘分区" aria-label="Permalink to “如何在 Linux 中使用 parted 对磁盘分区”">​</a></h1><blockquote><p>学习如何在 Linux 中使用 parted 命令来对存储设备分区。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bus-storage.png?itok=95-zvHYl" alt=""></p><p>在 Linux 中创建和删除分区是一种常见的操作，因为存储设备（如硬盘驱动器和 USB 驱动器）在使用之前必须以某种方式进行结构化。在大多数情况下，大型存储设备被分为称为<ruby>分区<rt>partition</rt></ruby>的独立部分。分区操作允许您将硬盘分割成独立的部分，每个部分都像是一个硬盘驱动器一样。如果您运行多个操作系统，那么分区是非常有用的。</p><p>在 Linux 中有许多强大的工具可以创建、删除和操作磁盘分区。在本文中，我将解释如何使用 <code>parted</code> 命令，这对于大型磁盘设备和许多磁盘分区尤其有用。<code>parted</code> 与更常见的 <code>fdisk</code> 和 <code>cfdisk</code> 命令之间的区别包括:</p>',5)),n("ul",null,[n("li",null,[s[1]||(s[1]=n("strong",null,"GPT 格式：",-1)),s[2]||(s[2]=n("code",null,"parted",-1)),s[3]||(s[3]=a(" 命令可以创建全局惟一的标识符分区表 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/GUID_Partition_Table"},{default:p(()=>[...s[0]||(s[0]=[a("GPT",-1)])]),_:1}),s[4]||(s[4]=a("，而 ",-1)),s[5]||(s[5]=n("code",null,"fdisk",-1)),s[6]||(s[6]=a(" 和 ",-1)),s[7]||(s[7]=n("code",null,"cfdisk",-1)),s[8]||(s[8]=a(" 则仅限于 DOS 分区表。",-1))]),s[13]||(s[13]=n("li",null,[n("strong",null,"更大的磁盘："),a(" DOS 分区表可以格式化最多 2TB 的磁盘空间，尽管在某些情况下最多可以达到 16TB。然而，一个 GPT 分区表可以处理最多 8ZiB 的空间。")],-1)),s[14]||(s[14]=n("li",null,[n("strong",null,"更多的分区："),a(" 使用主分区和扩展分区，DOS 分区表只允许 16 个分区。在 GPT 中，默认情况下您可以得到 128 个分区，并且可以选择更多的分区。")],-1)),n("li",null,[s[10]||(s[10]=n("strong",null,"可靠性：",-1)),s[11]||(s[11]=a(" 在 DOS 分区表中，只保存了一份分区表备份，在 GPT 中保留了两份分区表的备份（在磁盘的起始和结束部分），同时 GPT 还使用了 ",-1)),i(e,{href:"https://en.wikipedia.org/wiki/Cyclic_redundancy_check"},{default:p(()=>[...s[9]||(s[9]=[a("CRC",-1)])]),_:1}),s[12]||(s[12]=a(" 校验和来检查分区表的完整性，在 DOS 分区中并没有实现。",-1))])]),s[31]||(s[31]=l(`<p>由于现在的磁盘更大，需要更灵活地使用它们，建议使用 <code>parted</code> 来处理磁盘分区。大多数时候，磁盘分区表是作为操作系统安装过程的一部分创建的。在向现有系统添加存储设备时，直接使用 <code>parted</code> 命令非常有用。</p><h3 id="尝试一下-parted" tabindex="-1">尝试一下 parted <a class="header-anchor" href="#尝试一下-parted" aria-label="Permalink to “尝试一下 parted”">​</a></h3><p>下面解释了使用 <code>parted</code> 命令对存储设备进行分区的过程。为了尝试这些步骤，我强烈建议使用一块全新的存储设备或一种您不介意将其内容删除的设备。</p><h4 id="_1、列出分区" tabindex="-1">1、列出分区 <a class="header-anchor" href="#_1、列出分区" aria-label="Permalink to “1、列出分区”">​</a></h4><p>使用 <code>parted -l</code> 来标识你要进行分区的设备。一般来说，第一个硬盘 （<code>/dev/sda</code> 或 <code>/dev/vda</code> ）保存着操作系统， 因此要寻找另一个磁盘，以找到你想要分区的磁盘 (例如，<code>/dev/sdb</code>、<code>/dev/sdc</code>、 <code>/dev/vdb </code>、<code>/dev/vdc</code> 等)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo parted -l</span></span>
<span class="line"><span>[sudo] password for daniel: </span></span>
<span class="line"><span>Model: ATA RevuAhn_850X1TU5 (scsi)</span></span>
<span class="line"><span>Disk /dev/vdc: 512GB</span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B</span></span>
<span class="line"><span>Partition Table: msdos</span></span>
<span class="line"><span>Disk Flags: </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number  Start   End    Size   Type     File system  Flags</span></span>
<span class="line"><span> 1      1049kB  525MB  524MB  primary  ext4         boot</span></span>
<span class="line"><span> 2      525MB   512GB  512GB  primary               lvm</span></span></code></pre></div><h4 id="_2、打开存储设备" tabindex="-1">2、打开存储设备 <a class="header-anchor" href="#_2、打开存储设备" aria-label="Permalink to “2、打开存储设备”">​</a></h4><p>使用 <code>parted</code> 选中您要分区的设备。在这里例子中，是虚拟系统上的第三个磁盘（<code>/dev/vdc</code>）。指明你要使用哪一个设备非常重要。 如果你仅仅输入了 <code>parted</code> 命令而没有指定设备名字， 它会<strong>随机</strong>选择一个设备进行操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo parted /dev/vdc</span></span>
<span class="line"><span>GNU Parted 3.2</span></span>
<span class="line"><span>Using /dev/vdc</span></span>
<span class="line"><span>Welcome to GNU Parted! Type &#39;help&#39; to view a list of commands.</span></span>
<span class="line"><span>(parted)</span></span></code></pre></div><h4 id="_3、-设定分区表" tabindex="-1">3、 设定分区表 <a class="header-anchor" href="#_3、-设定分区表" aria-label="Permalink to “3、 设定分区表”">​</a></h4><p>设置分区表为 GPT ，然后输入 <code>Yes</code> 开始执行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) mklabel gpt </span></span>
<span class="line"><span>Warning: the existing disk label on /dev/vdc will be destroyed </span></span>
<span class="line"><span>and all data on this disk will be lost. Do you want to continue? </span></span>
<span class="line"><span>Yes/No? Yes</span></span></code></pre></div><p><code>mklabel</code> 和 <code>mktable</code> 命令用于相同的目的（在存储设备上创建分区表）。支持的分区表有：aix、amiga、bsd、dvh、gpt、mac、ms-dos、pc98、sun 和 loop。记住 <code>mklabel</code> 不会创建一个分区，而是创建一个分区表。</p><h4 id="_4、-检查分区表" tabindex="-1">4、 检查分区表 <a class="header-anchor" href="#_4、-检查分区表" aria-label="Permalink to “4、 检查分区表”">​</a></h4><p>查看存储设备信息:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) print </span></span>
<span class="line"><span>Model: Virtio Block Device (virtblk) </span></span>
<span class="line"><span>Disk /dev/vdc: 1396MB </span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B </span></span>
<span class="line"><span>Partition Table: gpt </span></span>
<span class="line"><span>Disk Flags: </span></span>
<span class="line"><span>Number Start End Size File system Name Flags</span></span></code></pre></div><h4 id="_5、-获取帮助" tabindex="-1">5、 获取帮助 <a class="header-anchor" href="#_5、-获取帮助" aria-label="Permalink to “5、 获取帮助”">​</a></h4><p>为了知道如何去创建一个新分区，输入： <code>(parted) help mkpart</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) help mkpart </span></span>
<span class="line"><span>  mkpart PART-TYPE [FS-TYPE] START END     make a partition</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        PART-TYPE is one of: primary, logical, extended</span></span>
<span class="line"><span>        FS-TYPE is one of: btrfs, nilfs2, ext4, ext3, ext2, fat32, fat16, hfsx, hfs+, hfs, jfs, swsusp,</span></span>
<span class="line"><span>        linux-swap(v1), linux-swap(v0), ntfs, reiserfs, hp-ufs, sun-ufs, xfs, apfs2, apfs1, asfs, amufs5,</span></span>
<span class="line"><span>        amufs4, amufs3, amufs2, amufs1, amufs0, amufs, affs7, affs6, affs5, affs4, affs3, affs2, affs1,</span></span>
<span class="line"><span>        affs0, linux-swap, linux-swap(new), linux-swap(old)</span></span>
<span class="line"><span>        START and END are disk locations, such as 4GB or 10%.  Negative values count from the end of the</span></span>
<span class="line"><span>        disk.  For example, -1s specifies exactly the last sector.</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        &#39;mkpart&#39; makes a partition without creating a new file system on the partition.  FS-TYPE may be</span></span>
<span class="line"><span>        specified to set an appropriate partition ID.</span></span></code></pre></div><h4 id="_6、-创建分区" tabindex="-1">6、 创建分区 <a class="header-anchor" href="#_6、-创建分区" aria-label="Permalink to “6、 创建分区”">​</a></h4><p>为了创建一个新分区（在这个例子中，分区 0 有 1396MB），输入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) mkpart primary 0 1396MB </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Warning: The resulting partition is not properly aligned for best performance </span></span>
<span class="line"><span>Ignore/Cancel? I </span></span>
<span class="line"><span></span></span>
<span class="line"><span>(parted) print </span></span>
<span class="line"><span>Model: Virtio Block Device (virtblk) </span></span>
<span class="line"><span>Disk /dev/vdc: 1396MB </span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B </span></span>
<span class="line"><span>Partition Table: gpt </span></span>
<span class="line"><span>Disk Flags: </span></span>
<span class="line"><span>Number Start   End     Size    File system Name Flags </span></span>
<span class="line"><span>1      17.4kB  1396MB  1396MB  primary</span></span></code></pre></div><p>文件系统类型（<code>fstype</code>）并不是在 <code>/dev/vdc1</code>上创建 ext4 文件系统。 DOS 分区表的分区类型是<ruby>主分区<rt>primary</rt></ruby>、<ruby>逻辑分区<rt>logical</rt></ruby>和<ruby>扩展分区<rt>extended</rt></ruby>。 在 GPT 分区表中，分区类型用作分区名称。 在 GPT 下必须提供分区名称；在上例中，<code>primary</code> 是分区名称，而不是分区类型。</p><h4 id="_7、-保存退出" tabindex="-1">7、 保存退出 <a class="header-anchor" href="#_7、-保存退出" aria-label="Permalink to “7、 保存退出”">​</a></h4><p>当你退出 <code>parted</code> 时，修改会自动保存。退出请输入如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(parted) quit</span></span>
<span class="line"><span>Information: You may need to update /etc/fstab.</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="谨记" tabindex="-1">谨记 <a class="header-anchor" href="#谨记" aria-label="Permalink to “谨记”">​</a></h3><p>当您添加新的存储设备时，请确保在开始更改其分区表之前确定正确的磁盘。如果您错误地更改了包含计算机操作系统的磁盘分区，会使您的系统无法启动。</p><hr>`,29)),n("p",null,[s[16]||(s[16]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/18/6/how-partition-disk-linux"},{default:p(()=>[...s[15]||(s[15]=[a("https://opensource.com/article/18/6/how-partition-disk-linux",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/daniel-oh"},{default:p(()=>[...s[17]||(s[17]=[a("Daniel Oh",-1)])]),_:1}),s[22]||(s[22]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[18]||(s[18]=[a("lujun9972",-1)])]),_:1}),s[23]||(s[23]=a(" 译者：",-1)),i(e,{href:"https://github.com/amwps290"},{default:p(()=>[...s[19]||(s[19]=[a("amwps290",-1)])]),_:1}),s[24]||(s[24]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[25]||(s[25]=[a("LCTT",-1)])]),_:1}),s[28]||(s[28]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[26]||(s[26]=[a("Linux中国",-1)])]),_:1}),s[29]||(s[29]=a(" 荣誉推出",-1))])])}const y=t(u,[["render",c]]);export{T as __pageData,y as default};
